// @vitest-environment jsdom
import { expect, test, vi, beforeEach } from 'vitest';
import { screen, fireEvent, waitFor, act } from '@testing-library/react';
import '@testing-library/jest-dom';
import { QueuePopupModal } from './QueuePopupModal';
import { renderWithKainBain } from '../../testUtils';
import { invalidateObservability } from '../../services/observabilityEvents';
import React from 'react';

vi.mock('../../services/api', () => ({
  api: {
    observabilityStatus: vi.fn(async () => ({
      observability: {
        queue: [
          { id: 'task-1', title: 'First', projectName: 'P', currentStageName: 'Work', queueOrder: 1, priorityReason: 'Queued' },
        ],
      },
    })),
    getRunnerMonitor: vi.fn(async () => ({ liveAssignments: [] })),
    systemStatus: vi.fn(async () => ({ build: null })),
    deployChangelog: vi.fn(async () => ({ changelog: null, reason: 'not-baked' })),
  },
}));

import { api } from '../../services/api';

beforeEach(() => {
  vi.clearAllMocks();
  api.observabilityStatus.mockResolvedValue({
    observability: {
      queue: [
        { id: 'task-1', title: 'First', projectName: 'P', currentStageName: 'Work', queueOrder: 1, priorityReason: 'Queued' },
      ],
    },
  });
});

test('opens and lists queue rows in order', async () => {
  const onClose = vi.fn();
  const setSelectedTask = vi.fn();
  renderWithKainBain(<QueuePopupModal counted={2} onClose={onClose} />, { setSelectedTask, engineState: { openQueueDepth: 2 } });
  await waitFor(() => expect(screen.getByTestId('queue-item-task-1')).toBeInTheDocument());
  expect(screen.getByText('First')).toBeInTheDocument();
  fireEvent.click(screen.getByTestId('queue-item-task-1'));
  expect(setSelectedTask).toHaveBeenCalled();
  fireEvent.click(screen.getByRole('button', { name: 'Close queue' }));
  expect(onClose).toHaveBeenCalled();
});

test('empty state renders Queue is Clear', async () => {
  api.observabilityStatus.mockResolvedValue({ observability: { queue: [] } });
  renderWithKainBain(<QueuePopupModal counted={0} onClose={() => {}} />, { engineState: { openQueueDepth: 0 } });
  await waitFor(() => expect(screen.getByText('Queue is Clear')).toBeInTheDocument());
});

test('error state shows retry', async () => {
  api.observabilityStatus.mockRejectedValueOnce(new Error('boom'));
  renderWithKainBain(<QueuePopupModal counted={1} onClose={() => {}} />, { engineState: { openQueueDepth: 1 } });
  await waitFor(() => expect(screen.getByRole('alert')).toBeInTheDocument());
  api.observabilityStatus.mockResolvedValue({ observability: { queue: [] } });
  fireEvent.click(screen.getByRole('button', { name: 'Retry' }));
  await waitFor(() => expect(screen.getByText('Queue is Clear')).toBeInTheDocument());
});

test('dialog panel carries the shared modal surface (sized, surfaced, clipped)', async () => {
  renderWithKainBain(<QueuePopupModal counted={2} onClose={() => {}} />, { engineState: { openQueueDepth: 2 } });
  const dialog = await screen.findByRole('dialog');
  // Same panel contract as ChangelogModal: bounded width/height, theme
  // surface, rounded border, and overflow clipping — without it the rows
  // float over the page with no panel at all.
  expect(dialog).toHaveClass('max-w-2xl');
  expect(dialog).toHaveClass('bg-surface-container');
  expect(dialog).toHaveClass('overflow-hidden');
});

test('reconciliation note shows counts', async () => {
  renderWithKainBain(<QueuePopupModal counted={3} onClose={() => {}} />, { engineState: { openQueueDepth: 3 } });
  await waitFor(() => expect(screen.getByTestId('queue-reconciliation')).toBeInTheDocument());
  expect(screen.getByTestId('queue-reconciliation')).toHaveTextContent('3 open tasks counted · 1 shown');
});

test('counted-but-empty queue says nothing runs next and explains the gap', async () => {
  // All counted tasks are failed/waiting-human: the dispatch list is empty,
  // so the header must not claim "#1 runs next".
  api.observabilityStatus.mockResolvedValue({ observability: { queue: [] } });
  renderWithKainBain(<QueuePopupModal counted={3} onClose={() => {}} />, { engineState: { openQueueDepth: 3 } });
  await waitFor(() => expect(screen.getByText('Queue is Clear')).toBeInTheDocument());
  expect(screen.getByText(/#— runs next/)).toBeInTheDocument();
  expect(screen.queryByText(/#1 runs next/)).not.toBeInTheDocument();
  const note = screen.getByTestId('queue-reconciliation');
  expect(note).toHaveTextContent('3 open tasks counted · 0 shown');
  expect(note.parentElement).toHaveTextContent(/human-stage tasks count toward the number but never dispatch/);
});

test('a failed refresh keeps the last known rows visible under the alert', async () => {
  renderWithKainBain(<QueuePopupModal counted={1} onClose={() => {}} />, { engineState: { openQueueDepth: 1 } });
  await waitFor(() => expect(screen.getByTestId('queue-item-task-1')).toBeInTheDocument());

  // Push a failing refresh through the real observability event bus (the
  // hook subscribes to it; the event debounce fires one refresh ~500ms later).
  api.observabilityStatus.mockRejectedValueOnce(new Error('network down'));
  act(() => {
    invalidateObservability('tasks-changed', { taskId: 'task-1' });
  });
  await waitFor(() => expect(screen.getByRole('alert')).toBeInTheDocument(), { timeout: 3000 });
  // Fail-safe: the previously loaded row is still rendered under the alert.
  expect(screen.getByTestId('queue-item-task-1')).toBeInTheDocument();
  expect(screen.getByRole('alert')).toHaveTextContent('Showing the last known queue below');

  // Retry recovers: the alert clears and the row is still there.
  api.observabilityStatus.mockResolvedValueOnce({ observability: { queue: [{ id: 'task-1', title: 'First', projectName: 'P', currentStageName: 'Work', queueOrder: 1 }] } });
  fireEvent.click(screen.getByRole('button', { name: 'Retry' }));
  await waitFor(() => expect(screen.queryByRole('alert')).not.toBeInTheDocument());
  expect(screen.getByTestId('queue-item-task-1')).toBeInTheDocument();
});

test('malformed queue payload renders the empty state instead of crashing', async () => {
  api.observabilityStatus.mockResolvedValue({ observability: { queue: 'not-an-array' } });
  renderWithKainBain(<QueuePopupModal counted={0} onClose={() => {}} />, { engineState: { openQueueDepth: 0 } });
  await waitFor(() => expect(screen.getByText('Queue is Clear')).toBeInTheDocument());
});

import { useEffect, useRef, useState } from 'react';
import { api } from '../services/api';
import { subscribeObservability } from '../services/observabilityEvents';
import { logger } from '../services/logger';

/***
 * MARK: useScheduledQueue
 * @description Shared frontend hook for the dispatch-ordered queue shown by the
 *   Now Playing bar's queue popup (and any future queue surface). Data source
 *   is the global observability snapshot (`api.observabilityStatus(undefined)`
 *   serves every project in dispatch order, so no new endpoint was needed).
 *   Fetches on enable only, refreshes on observability invalidations, and
 *   keeps a 15 s safety poll plus visibility/focus returns. The monitor
 *   dashboard deliberately keeps its own inline fetch: it publishes metrics
 *   and queue atomically from one response with monitor-only guards
 *   (TASK_UPDATED active-task filter, hidden-tab gating, a staleness rule),
 *   which this queue-only hook does not replicate. The return contract is
 *   exactly four fields (`items`, `loading`, `error`, `refresh`) — callers
 *   destructure those, nothing else. A missing API method surfaces as
 *   `error`, never as a silent empty queue; a malformed payload logs a
 *   warning and fails safe to an empty list.
 * @example const { items, loading, error, refresh } = useScheduledQueue({ projectScope: 'all', enabled: isOpen })
 * @param {Object} [opts]
 * @param {string} [opts.projectScope='all'] - 'all' or a project id.
 * @param {boolean} [opts.enabled=false] - Fetching is off until this is true.
 * @returns {{
 *   items: Array<Object>,
 *   loading: boolean,
 *   error: string|null,
 *   refresh: () => void,
 * }}
 ***/
export function useScheduledQueue({ projectScope = 'all', enabled = false } = {}) {
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const mountedRef = useRef(true);
  const fetchInFlightRef = useRef(false);
  const pendingRefreshRequestedRef = useRef(false);

  useEffect(() => {
    mountedRef.current = true;
    return () => {
      mountedRef.current = false;
    };
  }, []);

  const fetchQueue = async (refresh = false) => {
    if (!enabled) return;
    if (fetchInFlightRef.current) {
      if (refresh) pendingRefreshRequestedRef.current = true;
      return;
    }
    fetchInFlightRef.current = true;
    pendingRefreshRequestedRef.current = false;
    if (mountedRef.current) {
      setLoading(true);
    }
    try {
      const projectId = projectScope && projectScope !== 'all' ? projectScope : undefined;
      if (typeof api?.observabilityStatus !== 'function') {
        throw new Error('Queue endpoint is unavailable');
      }
      const response = await api.observabilityStatus(projectId, refresh);
      if (!mountedRef.current) return;
      const rawQueue =
        response?.observability?.queue ??
        response?.queue ??
        (Array.isArray(response) ? response : null);
      if (rawQueue != null && !Array.isArray(rawQueue)) {
        logger.warn('Scheduled queue payload was not an array; treating as empty');
        setItems([]);
      } else {
        setItems(rawQueue ?? []);
      }
      setError(null);
    } catch (err) {
      logger.error('Failed to fetch scheduled queue', err);
      if (mountedRef.current) {
        setError(err?.message || 'Failed to load queue');
      }
    } finally {
      fetchInFlightRef.current = false;
      if (mountedRef.current) {
        setLoading(false);
      }
      if (mountedRef.current && pendingRefreshRequestedRef.current) {
        pendingRefreshRequestedRef.current = false;
        void fetchQueue(true);
      }
    }
  };

  useEffect(() => {
    if (!enabled) return undefined;
    void fetchQueue();
    return undefined;
    // eslint-disable-next-line react-hooks/exhaustive-deps -- fetchQueue closes over enabled/projectScope which are already deps; its identity is intentionally unstable to let the compiler auto-memoize
  }, [enabled, projectScope]);

  useEffect(() => {
    if (!enabled) return undefined;
    let debounceTimer = null;
    const scheduleRefresh = () => {
      pendingRefreshRequestedRef.current = true;
      if (!debounceTimer) {
        debounceTimer = setTimeout(() => {
          debounceTimer = null;
          if (mountedRef.current) {
            void fetchQueue(true);
          }
        }, 500);
      }
    };
    const unsubscribe = subscribeObservability((event) => {
      if (
        event?.projectId &&
        projectScope &&
        projectScope !== 'all' &&
        event.projectId !== projectScope
      ) {
        return;
      }
      scheduleRefresh();
    });
    const interval = setInterval(() => void fetchQueue(true), 15000);
    const onVisibility = () => {
      if (document.visibilityState !== 'hidden') void fetchQueue(true);
    };
    document.addEventListener('visibilitychange', onVisibility);
    window.addEventListener('focus', onVisibility);
    return () => {
      unsubscribe();
      clearInterval(interval);
      clearTimeout(debounceTimer);
      document.removeEventListener('visibilitychange', onVisibility);
      window.removeEventListener('focus', onVisibility);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps -- fetchQueue closes over enabled/projectScope which are already deps; its identity is intentionally unstable to let the compiler auto-memoize
  }, [enabled, projectScope]);

  const refresh = () => {
    void fetchQueue(true);
  };

  return { items, loading, error, refresh };
}

/***
 * MARK: useScheduledQueue default
 * @description Default export alias for useScheduledQueue.
 * @example useScheduledQueue({ enabled: true }) => { items: [], loading: false }
 ***/
export default useScheduledQueue;
